hl.bind(mainMod .. " + " .. "CTRL" .. " + " .. "XF86LaunchA", hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot.sh monitor"))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "XF86LaunchA", hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot.sh window"))
