hl.bind(mainMod .. " + " .. "L", hl.dsp.layout("mfact +0.05"), { repeating = true })
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "L", hl.dsp.exec_cmd("systemctl suspend"))
hl.bind(mainMod .. " + " .. "F", hl.dsp.window.fullscreen())

-- Master Layout Control
hl.bind(mainMod .. " + " .. "Z", hl.dsp.exec_cmd("~/.config/hypr/scripts/toggle-layout.sh"))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "Return", hl.dsp.layout("swapwithmaster"))
hl.bind(mainMod .. " + " .. "J", hl.dsp.layout("cyclenext"))
hl.bind(mainMod .. " + " .. "K", hl.dsp.layout("cycleprev"))
hl.bind(mainMod .. " + " .. "I", hl.dsp.layout("addmaster"))
hl.bind(mainMod .. " + " .. "D", hl.dsp.layout("removemaster"))

-- Sets the layout to "Stacked" (Horizontal Split)
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "H", hl.dsp.layout("orientationtop"))

-- Sets the layout to "Side-by-Side" (Vertical Split)
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "V", hl.dsp.layout("orientationleft"))

